import React, { useCallback, useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import "./LilAgents.css";

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// Two lil companions that stroll on top of the hero stat tiles.
// Clicking one opens its mini glass terminal.
//
// Each bot carries a five-stop tone ramp rather than a flat two-colour
// gradient — the sprite reads as a solid object only because every surface
// gets a highlight, a midtone and a core shadow drawn from the same ramp.
// hueA/hueB stay as-is; the CSS still keys the antenna, focus ring, greeting
// heart and popover link off them.
const AGENTS = [
  {
    id: "bolt",
    name: "Bolt",
    role: "builder bot",
    hueA: "#ff7847",
    hueB: "#ff4d8d",
    tint: "#ffcbab",
    light: "#ff9a6b",
    mid: "#ff7847",
    deep: "#ef5583",
    shade: "#8d2f56",
    eye: "#ffd9b0",
    phrases: [
      "shipping ideas…",
      "compiling dreams ⚙️",
      "deploying to prod 🚀",
      "0 bugs found (today)",
      "refactoring reality…",
    ],
    cmd: "$ bolt status",
    lines: [
      "▸ 26+ projects shipped",
      "▸ 4 systems in production",
      // Keep this employer-agnostic — the bots shouldn't need editing on a
      // job change. Same goes for the phrases above.
      "✓ always building something new",
    ],
  },
  {
    id: "pixel",
    name: "Pixel",
    role: "research bot",
    hueA: "#7c5cff",
    hueB: "#38bdf8",
    tint: "#cfc9ff",
    light: "#9d88ff",
    mid: "#7c5cff",
    deep: "#4f8fe3",
    shade: "#2c3a7d",
    eye: "#8fecff",
    phrases: [
      "reading 60+ RAG nodes…",
      "connecting the dots…",
      "thinking really hard 🧠",
      "benchmarking vibes…",
      "found a cool paper!",
    ],
    cmd: '$ pixel ask "what\'s inside?"',
    lines: [
      "▸ RAG brain · 60+ knowledge nodes",
      "▸ 6 collaborating agents",
      "✓ all real, all running",
    ],
  },
];

// The lumpy cloud silhouette, reused three ways: filled, as a clip path, and
// offset for the rim-light mask. One definition means the three can't drift
// out of register. Sized so the head reads big-but-carryable — roughly 1.8x
// the torso width; much past that and the bot looks top-heavy rather than cute.
const CLOUD = (
  <>
    <rect x="19" y="18" width="34" height="21" rx="10.5" />
    <circle cx="36" cy="18" r="11.5" />
    <circle cx="26" cy="20" r="8.5" />
    <circle cx="46" cy="20" r="8.5" />
    <circle cx="21" cy="27" r="7.5" />
    <circle cx="51" cy="27" r="7.5" />
  </>
);

// Where the bot is in its 28s trip decides how it should be moving. These
// thresholds mirror the lilTripR/lilTripL keyframes exactly — the walk legs,
// the two gap crossings, the meeting, and the long rest at home. Sorted, so
// the last threshold at or below the current progress wins.
const GAIT_AT = [
  [0, "walk"],
  [0.1, "hop"],
  [0.14, "walk"],
  [0.2, "greet"],
  [0.26, "walk"],
  [0.345, "hop"],
  [0.38, "walk"],
  [0.48, "idle"],
];

function gaitFor(progress) {
  let gait = "idle";
  for (const [from, name] of GAIT_AT) {
    if (progress >= from) gait = name;
  }
  return gait;
}

// Which way the bot is facing. Mirrored only while actually walking leftward;
// both bots rest facing forward. The flip lands a little BEFORE the leg it
// belongs to — 0.245 is still inside the meeting, 0.98 is still parked at
// home — so the turn always plays while the bot is standing still rather than
// halfway through a slide. Bolt walks out rightward and home leftward; Pixel
// does the opposite, so each is mirrored on the other's leg.
function facingFor(progress, walksRightFirst) {
  const flipped = walksRightFirst
    ? progress >= 0.245 && progress < 0.5
    : progress < 0.245 || progress >= 0.98;
  return flipped ? "left" : "right";
}

// A cloud-headed pet built to move like a real walker rather than a floating
// icon. Structure exists to keep motions independent:
//   .lil-turn     180° turn-around at each reversal
//   .lil-bob      vertical travel — walk bob, hop, or idle breathing
//   .lil-head     secondary lag, so the head settles a beat after the body
//   .lil-arm      greeting wave, on the shared 28s schedule
//   .lil-arm-swing  walk/hop arm motion, nested inside .lil-arm so the wave
//                   and the swing compose instead of overwriting each other
//   .lil-foot-*   legs swinging from the hip
// Depth comes from a userSpaceOnUse ramp shared by every surface (per-shape
// gradients would seam where the cloud circles overlap), a core shadow, an
// occlusion pool where the head meets the torso, and a rim light.
function AgentSprite({ agent }) {
  const id = (part) => `lil-${agent.id}-${part}`;
  const head = id("head");
  const body = id("body");
  const arm = id("arm");
  const foot = id("foot");
  const core = id("core");
  const spec = id("spec");
  const clip = id("clip");
  const rim = id("rim");

  return (
    <svg className="lil-svg" viewBox="0 0 72 78" aria-hidden="true">
      <defs>
        <linearGradient
          id={head}
          gradientUnits="userSpaceOnUse"
          x1="20"
          y1="7"
          x2="54"
          y2="39"
        >
          <stop offset="0" stopColor={agent.light} />
          <stop offset="0.55" stopColor={agent.mid} />
          <stop offset="1" stopColor={agent.deep} />
        </linearGradient>

        <linearGradient
          id={body}
          gradientUnits="userSpaceOnUse"
          x1="24"
          y1="37"
          x2="48"
          y2="60"
        >
          <stop offset="0" stopColor={agent.mid} />
          <stop offset="1" stopColor={agent.deep} />
        </linearGradient>

        <linearGradient
          id={arm}
          gradientUnits="userSpaceOnUse"
          x1="15"
          y1="39"
          x2="57"
          y2="54"
        >
          <stop offset="0" stopColor={agent.mid} />
          <stop offset="1" stopColor={agent.deep} />
        </linearGradient>

        {/* Legs sit deepest in shadow so they read as furthest from the light */}
        <linearGradient
          id={foot}
          gradientUnits="userSpaceOnUse"
          x1="27"
          y1="56"
          x2="45"
          y2="72"
        >
          <stop offset="0" stopColor={agent.deep} />
          <stop offset="1" stopColor={agent.shade} />
        </linearGradient>

        <radialGradient
          id={core}
          gradientUnits="userSpaceOnUse"
          cx="36"
          cy="42"
          r="24"
        >
          <stop offset="0" stopColor={agent.shade} stopOpacity="0.6" />
          <stop offset="1" stopColor={agent.shade} stopOpacity="0" />
        </radialGradient>

        <radialGradient
          id={spec}
          gradientUnits="userSpaceOnUse"
          cx="27"
          cy="14"
          r="12"
        >
          <stop offset="0" stopColor={agent.tint} stopOpacity="0.7" />
          <stop offset="1" stopColor={agent.tint} stopOpacity="0" />
        </radialGradient>

        <clipPath id={clip}>{CLOUD}</clipPath>

        {/* Rim = silhouette MINUS the same silhouette nudged down-right, which
            leaves a crescent along the lit edge. Fills, not strokes — stroking
            the shapes draws every interior overlap too, which reads as a
            scribble inside the head. */}
        <mask
          id={rim}
          maskUnits="userSpaceOnUse"
          x="0"
          y="0"
          width="72"
          height="78"
        >
          <g fill="#fff">{CLOUD}</g>
          <g fill="#000" transform="translate(2.2 2.2)">
            {CLOUD}
          </g>
        </mask>
      </defs>

      <ellipse className="lil-shadow" cx="36" cy="75" rx="15" ry="3" />

      {/* Everything that turns lives in here; the ground shadow stays put */}
      <g className="lil-turn">
        <g className="lil-bob">
          {/* Limbs first — the torso overlaps them and hides their roots */}
          <g className="lil-arm lil-arm-l">
            <rect
              className="lil-arm-swing"
              x="15"
              y="39"
              width="7.5"
              height="15"
              rx="3.75"
              fill={`url(#${arm})`}
            />
          </g>
          <g className="lil-arm lil-arm-r">
            <rect
              className="lil-arm-swing"
              x="49.5"
              y="39"
              width="7.5"
              height="15"
              rx="3.75"
              fill={`url(#${arm})`}
            />
          </g>
          <rect
            className="lil-foot lil-foot-l"
            x="27"
            y="56"
            width="8"
            height="16"
            rx="4"
            fill={`url(#${foot})`}
          />
          <rect
            className="lil-foot lil-foot-r"
            x="37"
            y="56"
            width="8"
            height="16"
            rx="4"
            fill={`url(#${foot})`}
          />

          {/* Torso */}
          <rect
            x="24"
            y="37"
            width="24"
            height="23"
            rx="11"
            fill={`url(#${body})`}
          />
          <ellipse
            cx="36"
            cy="58"
            rx="11"
            ry="3.6"
            fill={agent.shade}
            opacity="0.3"
          />
          {/* Pooled occlusion where the head sits on the torso */}
          <ellipse
            cx="36"
            cy="39"
            rx="13"
            ry="4.2"
            fill={agent.shade}
            opacity="0.45"
          />

          {/* Chest prompt */}
          <g className="lil-chest">
            <path d="M32 45 l3 3 l-3 3" />
            <path d="M37.5 51 h4.5" />
          </g>

          <g className="lil-head">
            <g className="lil-antenna-grp">
              <line className="lil-antenna" x1="36" y1="9" x2="36" y2="4" />
              <circle
                className="lil-antenna-tip"
                cx="36"
                cy="3"
                r="2"
                fill={agent.hueA}
              />
            </g>

            {/* Cloud head — overlapping shapes sharing one userSpaceOnUse ramp */}
            <g fill={`url(#${head})`}>{CLOUD}</g>

            {/* Shading pass, clipped to the silhouette */}
            <g clipPath={`url(#${clip})`}>
              <ellipse cx="36" cy="42" rx="24" ry="13" fill={`url(#${core})`} />
              <circle cx="27" cy="14" r="12" fill={`url(#${spec})`} />
            </g>
            <g className="lil-shine" mask={`url(#${rim})`}>
              <rect x="0" y="0" width="72" height="44" fill={agent.tint} />
            </g>

            <rect
              className="lil-face"
              x="24"
              y="17"
              width="24"
              height="14"
              rx="7"
            />
            <g className="lil-eyes">
              {/* Softened lid on top, deep curve beneath — content and sleepy.
                Square top corners here read as a scowl, hence the 0.7 radius. */}
              <g className="lil-eye">
                <path
                  d="M27.7 21 h5.6 a0.7 0.7 0 0 1 0.7 0.7 v1 a3.5 3.5 0 0 1 -7 0 v-1 a0.7 0.7 0 0 1 0.7 -0.7 z"
                  fill={agent.eye}
                />
                <circle cx="29" cy="23.4" r="0.85" fill="#fff" opacity="0.9" />
              </g>
              <g className="lil-eye">
                <path
                  d="M38.7 21 h5.6 a0.7 0.7 0 0 1 0.7 0.7 v1 a3.5 3.5 0 0 1 -7 0 v-1 a0.7 0.7 0 0 1 0.7 -0.7 z"
                  fill={agent.eye}
                />
                <circle cx="40" cy="23.4" r="0.85" fill="#fff" opacity="0.9" />
              </g>
            </g>
            {/* Cheeks light up on hover and when the two bots meet */}
            <g className="lil-blush">
              <ellipse cx="19" cy="30" rx="2.8" ry="1.7" />
              <ellipse cx="53" cy="30" rx="2.8" ry="1.7" />
            </g>
          </g>
        </g>
      </g>
    </svg>
  );
}

function LilAgents() {
  const [bubble, setBubble] = useState(null); // { agentId, text }
  const [openId, setOpenId] = useState(null);
  const [spinId, setSpinId] = useState(null); // alarm-shake + 3D spin on click
  const perchRef = useRef(null);
  const phraseIdx = useRef([0, 0]);

  // Alternate thought bubbles between the two agents
  useEffect(() => {
    let turn = 0;
    let hide = null;
    const show = () => {
      const agent = AGENTS[turn % 2];
      const i = phraseIdx.current[turn % 2];
      setBubble({
        agentId: agent.id,
        text: agent.phrases[i % agent.phrases.length],
      });
      phraseIdx.current[turn % 2] = i + 1;
      turn += 1;
      hide = setTimeout(() => setBubble(null), 3000);
    };
    show();
    const id = setInterval(show, 5600);
    return () => {
      clearInterval(id);
      if (hide) clearTimeout(hide);
    };
  }, []);

  // Drive each bot's gait from its own trip animation. Reading the progress
  // off the running animation (rather than a parallel timer) means the legs
  // can never drift out of step with the translation, and a paused trip —
  // hover or an open popover — freezes the gait with it for free.
  useEffect(() => {
    if (prefersReducedMotion()) return;
    const perch = perchRef.current;
    if (!perch) return;
    const bots = Array.from(perch.querySelectorAll(".lil-agent"));
    const current = new Map();
    let raf = null;
    let last = 0;

    const tick = (now) => {
      raf = requestAnimationFrame(tick);
      if (now - last < 60) return; // gait changes are seconds apart
      last = now;
      bots.forEach((bot, i) => {
        const trip = bot
          .getAnimations()
          .find(
            (a) => a.animationName && a.animationName.startsWith("lilTrip")
          );
        if (!trip || !trip.effect) return;
        const { progress } = trip.effect.getComputedTiming();
        if (progress == null) return;
        const gait = gaitFor(progress);
        const facing = facingFor(progress, i === 0);
        const state = `${gait}|${facing}`;
        if (current.get(bot) !== state) {
          current.set(bot, state);
          bot.dataset.gait = gait;
          bot.dataset.facing = facing;
        }
      });
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  // Pupils follow the cursor (desktop pointers only)
  useEffect(() => {
    if (prefersReducedMotion()) return;
    if (window.matchMedia && !window.matchMedia("(pointer: fine)").matches)
      return;
    const perch = perchRef.current;
    if (!perch) return;
    let raf = null;
    const onMove = (e) => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = null;
        perch.querySelectorAll(".lil-svg").forEach((svg) => {
          const r = svg.getBoundingClientRect();
          const dx = e.clientX - (r.left + r.width / 2);
          const dy = e.clientY - (r.top + r.height / 2);
          const len = Math.max(Math.hypot(dx, dy), 1);
          svg.style.setProperty("--eye-x", `${(dx / len) * 1.5}px`);
          svg.style.setProperty("--eye-y", `${(dy / len) * 1.1}px`);
        });
      });
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => {
      window.removeEventListener("mousemove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // Close the mini window on Escape or outside click
  useEffect(() => {
    if (!openId) return;
    const onKey = (e) => {
      if (e.key === "Escape") setOpenId(null);
    };
    const onClick = (e) => {
      if (perchRef.current && !perchRef.current.contains(e.target))
        setOpenId(null);
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("mousedown", onClick);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("mousedown", onClick);
    };
  }, [openId]);

  const toggle = useCallback((id) => {
    setOpenId((cur) => (cur === id ? null : id));
    if (!prefersReducedMotion()) {
      setSpinId(id);
      setTimeout(() => setSpinId((cur) => (cur === id ? null : cur)), 1100);
    }
  }, []);

  // Both bots share one 28s schedule, so a pause has to apply to the pair —
  // freezing only the one you touched lets the other walk straight through it.
  return (
    <div
      className={`pj-agents-perch${openId ? " lil-any-open" : ""}`}
      ref={perchRef}
    >
      {AGENTS.map((agent, i) => (
        <div
          key={agent.id}
          className={`lil-agent lil-agent-${i} ${
            openId === agent.id ? "lil-open" : ""
          } ${spinId === agent.id ? "lil-spin" : ""}`}
          style={{ "--lil-a": agent.hueA, "--lil-b": agent.hueB }}
        >
          {bubble && bubble.agentId === agent.id && openId !== agent.id && (
            <div className="lil-bubble" role="status">
              {bubble.text}
            </div>
          )}

          {openId === agent.id && (
            <div className="lil-popover">
              <div className="lil-popover-bar">
                <span className="lil-dot lil-dot-r" />
                <span className="lil-dot lil-dot-y" />
                <span className="lil-dot lil-dot-g" />
                <span className="lil-popover-title">
                  {agent.name} · {agent.role}
                </span>
              </div>
              <div className="lil-popover-body">
                <p className="lil-line lil-line-cmd">{agent.cmd}</p>
                {agent.lines.map((line, li) => (
                  <p
                    className="lil-line"
                    style={{ "--lil-delay": `${0.25 + li * 0.3}s` }}
                    key={li}
                  >
                    {line}
                  </p>
                ))}
                <Link className="lil-popover-link" to="/myspace">
                  meet all 9 live tools →
                </Link>
              </div>
            </div>
          )}

          <button
            type="button"
            className="lil-hit"
            onClick={() => toggle(agent.id)}
            aria-label={`Chat with ${agent.name}, ${agent.role}`}
            aria-expanded={openId === agent.id}
          >
            <span className="lil-lean">
              <AgentSprite agent={agent} />
            </span>
          </button>
          {/* <span className="lil-oof" aria-hidden="true">
            oof!
          </span> */}
          <span className="lil-name">{agent.name}</span>
        </div>
      ))}
    </div>
  );
}

export default LilAgents;
